using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private string? method;
    private string? path;
    private string? contentType;
    private string? body;
    private int status = 200;
    private string reply = """{"status":"approved"}""";

    public HttpPaymentGatewayTests()
    {
        var probe = new TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();

        var prefix = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(prefix);
        listener.Start();
        _ = Task.Run(Serve);
        client = new HttpClient { BaseAddress = new Uri(prefix) };
    }

    private async Task Serve()
    {
        while (listener.IsListening)
        {
            HttpListenerContext ctx;
            try { ctx = await listener.GetContextAsync(); }
            catch { return; }

            method = ctx.Request.HttpMethod;
            path = ctx.Request.Url!.AbsolutePath;
            contentType = ctx.Request.ContentType;
            using (var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8))
                body = await reader.ReadToEndAsync();

            var bytes = Encoding.UTF8.GetBytes(reply);
            ctx.Response.StatusCode = status;
            ctx.Response.ContentType = "application/json";
            await ctx.Response.OutputStream.WriteAsync(bytes);
            ctx.Response.Close();
        }
    }

    private Task<AuthorizationOutcome> Authorize(decimal amount = 12.5m, string currency = "eur") =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(amount, currency), CancellationToken.None);

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        await Authorize(12.5m, "eur");

        Assert.Equal("POST", method);
        Assert.Equal("/v1/authorizations", path);
        Assert.StartsWith("application/json", contentType);
        using var json = JsonDocument.Parse(body!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        reply = """{"status":"approved"}""";
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        reply = """{"status":"declined"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        reply = """{"id":"x1","status":"approved","risk":{"score":3}}""";
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_even_with_an_approving_body()
    {
        status = 402;
        reply = """{"status":"approved"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_with_an_empty_body_is_a_decline()
    {
        status = 402;
        reply = "";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failure_statuses_are_raised_not_treated_as_declines(int code)
    {
        status = code;
        reply = """{"status":"declined"}""";
        var ex = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal((HttpStatusCode)code, ex.StatusCode);
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"outcome":"approved"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("null")]
    public async Task An_answer_that_does_not_clearly_say_approved_is_never_approved(string answer)
    {
        reply = answer;
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("")]
    [InlineData("not json")]
    public async Task An_unreadable_answer_is_raised_not_approved(string answer)
    {
        reply = answer;
        await Assert.ThrowsAnyAsync<Exception>(Authorize);
    }

    public void Dispose()
    {
        listener.Close();
        client.Dispose();
    }
}
